  for (let z = -140; z <= 140; z += 16) { palm(-132, z + 4); palm(-108, z - 6); }
  for (let z = -120; z <= 120; z += 24) palm(-150 + rnd() * 6, z);
  for (let i = 0; i < 12; i++) palm(-60 + rnd() * 190, -140 + rnd() * 280);
