      const on = Math.floor(S.time * 6) % 2 === 0;
      u.lightbar.userData.r.material.color.setHex(on ? C.policeRed : 0x550000);
      u.lightbar.userData.b.material.color.setHex(on ? 0x220044 : C.policeBlue);
